# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows

def make(last, first, section, email):
    return Student("1", last, first, section, email)

class ContactRowsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            make("Varrow", "Ines", "A", "iv@example.edu"),
            make("Thistle", "Bram", "BB", "bt@example.edu")
        ])
        self.assertEqual(rows, [
            "Thistle, Bram  BB  bt@example.edu",
            "Varrow, Ines   A   iv@example.edu"
        ])

    def test_missing_email_names_student(self):
        students = [
            make("Quillon", "Sefa", "A", None),
            make("Varrow", "Ines", "A", "iv@example.edu")
        ]
        with self.assertRaises(ProjectError) as ctx:
            contact_rows(students)
        self.assertIn("Quillon, Sefa", str(ctx.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows([make("Dunmere", "Piet", "B", "")])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
